application.css:
* {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #eef2f7;
}

body {
  margin: 0;
  min-width:  body;
  background: #eef2f7;
}

.app-shell {
  width: min(100% - 2rem, 720px);
  margin: 0 auto;
  padding: 3rem 0;
}

.app-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .5rem;
  color: #2457a6;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(2rem, 6vw, 3rem);
  line-height: 1.1;
}

h2 {
  margin-bottom: 1rem;
  font-size: 1.15rem;
}

.intro {
  margin-bottom: 0;
  color: #4c5870;
}

.todo-panel {
  margin-bottom: 1.25rem;
  padding: 1.35rem;
  border: 1px solid #d5dce8;
  border-radius: .8rem;
  background: #fff;
  box-shadow: 0 .25rem .9rem rgb(23 32 51 / 6%);
}

.input-row {
  display: flex;
  align-items: end;
  gap: .75rem;
}

.field-group {
  flex: 1;
}

label {
  display: block;
  margin-bottom: .4rem;
  font-weight: 650;
}

input[type="text"] {
  width: 100%;
  min-height: 2.75rem;
  padding: .65rem .75rem;
  border: 1px solid #8b98ae;
  border-radius: .4rem;
  color: #172033;
  font: inherit;
}

button {
  min-height: 2.75rem;
  border: 0;
  border-radius: .4rem;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.primary-button {
  padding: .65rem 1.1rem;
  background: #2457a6;
  color: #fff;
}

.primary-button:hover {
  background: #194584;
}

button:focus-visible, input:focus-visible {
  outline: 3px solid #f0a202;
  outline-offset: 2px;
}

.form-error {
  margin: .65rem 0 0;
  color: #a32929;
  font-size: .9rem;
  font-weight: 600;
}

.list-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.list-heading h2 {
  margin-bottom: 0;
}

.count {
  margin-bottom: 0;
  color: #4c5870;
  font-size: .9rem;
}

.count span:first-child {
  color: #172033;
  font-weight: 750;
}

.task-list {
  display: grid;
  gap: .65rem;
  margin: 1.25rem 0 0;
  padding: 0;
  list-style: none;
}

.task-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .75rem;
  border: 1px solid #d5dce8;
  border-radius: .5rem;
  background: #f8faff;
}

.task-toggle {
  width: 1.15rem;
  height: 1.15rem;
  flex: 0 0 auto;
  accent-color: #2457a6;
}

.task-text {
  flex: 1;
  overflow-wrap: anywhere;
}

.task-item.completed .task-text {
  color: #59657a;
  text-decoration: line-through;
}

.delete-button {
  padding: .35rem .55rem;
  color: #a32929;
  background: transparent;
}

.delete-button:hover {
  background: #fbecec;
}

.empty-message {
  margin: 1.25rem 0 0;
  color: #59657a;
  text-align: center;
}

@media (max-width: 520px) {
  .app-shell {
    width: min(100% - 1rem, 720px);
    padding: 2rem 0;
  }

  .input-row {
    align-items: stretch;
    flex-direction: column;
  }

  .primary-button {
    width: 100%;
  }
}

